/* Generated by tools/build.py from templates/*.json - do not edit by hand. */
window.SIGNOFF_TEMPLATES = [{"id":"requirements","title":"Requirements & Architecture","short":"Architecture","version":1,"description":"Review of firmware requirements, architecture, resource budgets, third-party code and, where it applies, functional safety.","sections":[{"id":"req-def","title":"Firmware Requirements","tags":[],"items":[{"id":"req-def-1","text":"Firmware requirements are written down and traced to the product and EE requirements","hint":"Each firmware requirement should name its parent (a system or EE requirement) so a change upstream shows what it touches.","tags":[],"severity":"major"},{"id":"req-def-2","text":"Every requirement has a verification method (test, analysis, inspection, or demonstration)","hint":"Use the Requirements tab: a requirement with no way to verify it can't be signed off.","tags":[],"severity":"major"},{"id":"req-def-3","text":"Timing requirements are quantified (latency, response time, update rates)","hint":"\"Fast\" isn't testable. E.g. \"relay off within 100 ms of a fault\" or \"display update within 50 ms of a touch\".","tags":[],"severity":"major"},{"id":"req-def-4","text":"Behavior on power-up, reset, and power loss is specified","hint":"What state are outputs in during boot? What is restored after a power cut, and what is lost?","tags":[],"severity":"major"},{"id":"req-def-5","text":"Error and fault behavior is specified, not just the happy path","hint":"List the faults the firmware must detect (sensor open or short, comms loss, storage full) and what it does for each.","tags":[],"severity":"major"},{"id":"req-def-6","text":"User-visible behavior (UI flows, LEDs, error codes) has a spec the product owner agreed to","hint":"Error codes and LED patterns end up in manuals and support scripts. Freeze them deliberately.","tags":[],"severity":"minor"},{"id":"req-def-7","text":"Regulatory and certification requirements that land on firmware are identified","hint":"E.g. radio duty cycle and region settings, IEC 60730 class B self-tests, EN 18031 / RED cybersecurity, IEC 62304.","tags":[],"severity":"major"}]},{"id":"req-arch","title":"Architecture","tags":[],"items":[{"id":"req-arch-1","text":"An architecture document shows the layers, modules, and their dependencies","hint":"A one-page block diagram is enough: HAL, drivers, middleware, application, and which way calls go.","tags":[],"severity":"major"},{"id":"req-arch-2","text":"The hardware abstraction is separated from application logic","hint":"Application code that touches registers directly can't be unit tested off target or ported to the next MCU.","tags":[],"severity":"major"},{"id":"req-arch-3","text":"Flash, RAM, and CPU budgets exist, with margin for the product's life","hint":"Plan to ship with at least 25–30% free flash and RAM so field updates have room to grow.","tags":[],"severity":"major"},{"id":"req-arch-4","text":"The execution model is chosen and justified (superloop, RTOS, event-driven)","hint":"Record why. The choice drives timing analysis, testing, and power management.","tags":[],"severity":"minor"},{"id":"req-arch-5","text":"The partition between processors is defined where there is more than one","hint":"Who owns which peripheral, how they talk, and how one updates or resets the other.","tags":["multi-core"],"severity":"major"},{"id":"req-arch-6","text":"State machines for the main modes are drawn and match the code","hint":"Modes such as boot, setup, run, fault, and update. Unhandled event/state pairs are a common source of field bugs.","tags":[],"severity":"minor"},{"id":"req-arch-7","text":"Configuration is separated from code (build variants, region, SKU)","hint":"Prefer one image with runtime configuration, or a small, named set of build variants.","tags":[],"severity":"minor"}]},{"id":"req-dep","title":"Third-Party Code","tags":[],"items":[{"id":"req-dep-1","text":"Every third-party component is listed with version, source, and license","hint":"SDKs, RTOS, stacks, libraries, vendor examples. This becomes the SBOM.","tags":[],"severity":"major"},{"id":"req-dep-2","text":"Licenses are compatible with how the product ships","hint":"GPL and LGPL components have obligations for linked, distributed binaries. Check with the client before shipping them.","tags":[],"severity":"major"},{"id":"req-dep-3","text":"Vendor SDK and stack versions are pinned, and the update policy is written down","hint":"Pin by version or commit. Unpinned SDK updates change behavior between builds.","tags":[],"severity":"minor"},{"id":"req-dep-4","text":"Local modifications to third-party code are kept as patches","hint":"So they can be re-applied when the upstream version changes.","tags":[],"severity":"minor"}]},{"id":"req-saf","title":"Functional Safety","tags":["safety","medical"],"items":[{"id":"req-saf-1","text":"The applicable safety standard and software class are identified","hint":"E.g. IEC 60730 class B for appliance controls, IEC 61508 SIL, IEC 62304 class A/B/C for medical.","tags":["safety","medical"],"severity":"critical"},{"id":"req-saf-2","text":"A hazard analysis identifies the firmware's contribution to each hazard","hint":"Each hazard the firmware can cause or must prevent, with the mitigation and how it's verified.","tags":["safety","medical"],"severity":"critical"},{"id":"req-saf-3","text":"Safety functions are isolated from non-safety code","hint":"Separate tasks or partitions, MPU regions, or a separate processor, so a bug elsewhere can't defeat them.","tags":["safety","medical"],"severity":"major"},{"id":"req-saf-4","text":"Required self-tests are implemented (CPU, RAM, flash CRC, clock)","hint":"IEC 60730 class B lists the self-tests by component. Vendor class B libraries cover most of them.","tags":["safety"],"severity":"major"},{"id":"req-saf-5","text":"Software of unknown provenance (SOUP) is listed with its risk assessment","hint":"IEC 62304 asks for each SOUP item's requirements and known anomalies.","tags":["medical"],"severity":"major"}]}]},{"id":"hw-interface","title":"Hardware Interface","short":"HW interface","version":1,"description":"Review of the firmware's view of the hardware: pin and peripheral configuration against the schematic, clocks, drivers, errata, sensing, outputs, and display.","sections":[{"id":"hsi-pin","title":"Pins & Peripherals","tags":[],"items":[{"id":"hsi-pin-1","text":"Pin assignments and alternate functions match the current schematic revision","hint":"Compare the pinmux (or the config tool's file) with the schematic net names, pin by pin. Revisions drift.","tags":[],"severity":"critical"},{"id":"hsi-pin-2","text":"Unused pins are set to a defined state","hint":"Analog or output-low per the datasheet's advice. Floating inputs draw current and pick up noise.","tags":[],"severity":"major"},{"id":"hsi-pin-3","text":"Outputs that drive actuators are safe from reset until firmware sets them","hint":"Check the pin's reset state and any external pull. A relay or heater must not pulse during boot.","tags":[],"severity":"critical"},{"id":"hsi-pin-4","text":"Pull-ups, pull-downs, and drive strength match what the circuit expects","hint":"Internal pulls duplicated or missing against the schematic; drive strength too high for EMI.","tags":[],"severity":"major"},{"id":"hsi-pin-5","text":"Peripheral instances and DMA channels are allocated without conflicts","hint":"Keep a table of which peripheral, DMA stream, and interrupt each driver owns.","tags":[],"severity":"major"},{"id":"hsi-pin-6","text":"The pin and peripheral table is generated or checked by a tool, not copied by hand","hint":"E.g. the vendor's config tool output, or a script that cross-checks the netlist.","tags":[],"severity":"minor"}]},{"id":"hsi-clk","title":"Clocks & Timing","tags":[],"items":[{"id":"hsi-clk-1","text":"The clock tree is configured as designed, and the derived frequencies are verified","hint":"Measure the system clock on an MCO pin or by timing a known loop on real hardware.","tags":[],"severity":"major"},{"id":"hsi-clk-2","text":"Peripheral clocks give baud rates and sample rates within tolerance","hint":"UART baud error under about 2%. Check every rate at every system clock setting used.","tags":[],"severity":"major"},{"id":"hsi-clk-3","text":"Crystal or oscillator startup failure is detected and handled","hint":"Use the clock security system or a startup timeout, and fall back to the internal oscillator.","tags":[],"severity":"major"},{"id":"hsi-clk-4","text":"Timer resolution and wrap-around are handled for every timebase","hint":"A 32-bit millisecond tick wraps after 49.7 days. Compare with subtraction, not absolute values.","tags":[],"severity":"minor"},{"id":"hsi-clk-5","text":"RTC accuracy and drift correction meet the timekeeping requirement","hint":"Calibrate the 32.768 kHz crystal or resync from the network.","tags":[],"severity":"minor"}]},{"id":"hsi-drv","title":"Drivers & Errata","tags":[],"items":[{"id":"hsi-drv-1","text":"The silicon errata for the exact part and revision are reviewed, and workarounds are in place","hint":"Note the die revision on the prototype boards. Errata differ between revisions.","tags":[],"severity":"critical"},{"id":"hsi-drv-2","text":"Every driver checks return codes and has timeouts on hardware waits","hint":"No unbounded while (!flag) loops. A stuck I2C bus must not hang the system.","tags":[],"severity":"major"},{"id":"hsi-drv-3","text":"I2C bus recovery is implemented for a slave holding SDA low","hint":"Clock out nine pulses and send a STOP, then reinitialize the peripheral.","tags":[],"severity":"major"},{"id":"hsi-drv-4","text":"Cache, DMA, and memory barriers are handled where the core has caches","hint":"Clean or invalidate around DMA buffers, or place them in non-cacheable memory.","tags":[],"severity":"major"},{"id":"hsi-drv-5","text":"External devices are initialized in the order their datasheets require","hint":"Power sequencing, reset-release delays, and the first register writes.","tags":[],"severity":"minor"},{"id":"hsi-drv-6","text":"Device IDs or WHO_AM_I registers are read at startup to detect missing or wrong parts","hint":"Makes second-source parts and assembly errors visible in production test.","tags":[],"severity":"minor"}]},{"id":"hsi-adc","title":"Sensing & Signal Processing","tags":["sensing"],"items":[{"id":"hsi-adc-1","text":"ADC sampling time and reference suit each source impedance","hint":"High-impedance sources need longer sample times or a buffer.","tags":["sensing"],"severity":"major"},{"id":"hsi-adc-2","text":"Filtering and averaging are designed for the noise and the response time required","hint":"Document the filter's cutoff or time constant and its effect on latency.","tags":["sensing"],"severity":"major"},{"id":"hsi-adc-3","text":"Calibration constants are stored, versioned, and range-checked on load","hint":"A blank or corrupt calibration must be detected and flagged, not used.","tags":["sensing"],"severity":"major"},{"id":"hsi-adc-4","text":"Open, short, and out-of-range sensor readings are detected","hint":"Report a sensor fault instead of acting on an impossible value.","tags":["sensing"],"severity":"major"},{"id":"hsi-adc-5","text":"Fixed-point scaling and overflow are analyzed, or floating point is used deliberately","hint":"Check the worst-case intermediate values. Note whether the FPU is used in interrupts.","tags":["sensing"],"severity":"minor"},{"id":"hsi-adc-6","text":"Self-heating and nearby heat sources are compensated where they affect a measurement","hint":"E.g. a temperature sensor near the MCU or the display backlight.","tags":["sensing"],"severity":"minor"}]},{"id":"hsi-act","title":"Outputs & Actuators","tags":["actuators","motor-control"],"items":[{"id":"hsi-act-1","text":"Outputs go to a safe state on any fault, reset, or watchdog timeout","hint":"Define the safe state per output. Verify it by forcing each fault on the bench.","tags":["actuators"],"severity":"critical"},{"id":"hsi-act-2","text":"Minimum on and off times, interlocks, and rate limits protect the load","hint":"E.g. compressor short-cycle protection, H-bridge dead time, relay contact wear.","tags":["actuators"],"severity":"major"},{"id":"hsi-act-3","text":"Output state is read back or confirmed where the hardware allows","hint":"Detect a welded relay or an open load.","tags":["actuators"],"severity":"major"},{"id":"hsi-act-4","text":"Control loops are tuned, with gains and limits documented","hint":"Anti-windup, output clamps, and behavior when the feedback sensor fails.","tags":["motor-control"],"severity":"major"},{"id":"hsi-act-5","text":"Overcurrent and stall protection respond within the hardware's limits","hint":"Firmware protection needs a known worst-case response time, or hardware protection behind it.","tags":["motor-control"],"severity":"critical"}]},{"id":"hsi-ui","title":"Display & Touch","tags":["display-ui"],"items":[{"id":"hsi-ui-1","text":"Display initialization follows the panel's power and reset sequence","hint":"VDDIO, VDD, reset release, init commands, then the backlight.","tags":["display-ui"],"severity":"minor"},{"id":"hsi-ui-2","text":"Touch input is debounced and filtered against false presses","hint":"Includes water, ESD, and a hand resting on the panel.","tags":["display-ui"],"severity":"major"},{"id":"hsi-ui-3","text":"The touch controller and display recover after ESD or a glitch without a full reset","hint":"Detect a stuck controller (no interrupts, bad ID) and reinitialize it.","tags":["display-ui"],"severity":"major"},{"id":"hsi-ui-4","text":"Frame buffer and graphics memory fit the RAM budget, including fonts and images","hint":"Count partial-refresh buffers and double buffering.","tags":["display-ui"],"severity":"minor"},{"id":"hsi-ui-5","text":"Text, units, and formats can be localized if the product needs it","hint":"Units (°C or °F), date and time formats, character sets.","tags":["display-ui"],"severity":"minor"}]}]},{"id":"boot-memory","title":"Startup, Memory & Faults","short":"Memory & faults","version":1,"description":"Review of startup, the memory map and linker script, stack and heap use, non-volatile storage, fault handling, and the watchdog.","sections":[{"id":"mem-boot","title":"Startup","tags":[],"items":[{"id":"mem-boot-1","text":"Startup code initializes .data and .bss, clocks, and the FPU before main","hint":"Review vendor startup files rather than trusting them. Check the vector table location.","tags":[],"severity":"major"},{"id":"mem-boot-2","text":"The reset cause is read, logged, and cleared at every boot","hint":"Power-on, brownout, watchdog, software, or pin reset. It's the first clue to field failures.","tags":[],"severity":"major"},{"id":"mem-boot-3","text":"Boot time to a working product is measured and meets the requirement","hint":"Measure from power applied to outputs ready and the UI responsive.","tags":[],"severity":"minor"},{"id":"mem-boot-4","text":"Option bytes or fuses are documented and set by the production process","hint":"Brownout level, boot pins, watchdog hardware start, read protection.","tags":[],"severity":"major"}]},{"id":"mem-map","title":"Memory & Linker","tags":[],"items":[{"id":"mem-map-1","text":"The linker script matches the part's memory map and the flash partition plan","hint":"Bootloader, application slots, configuration and storage regions don't overlap.","tags":[],"severity":"major"},{"id":"mem-map-2","text":"The map file is reviewed for size against the budget at each release","hint":"Track flash and RAM use per build so growth is noticed early.","tags":[],"severity":"major"},{"id":"mem-map-3","text":"Stack sizes are measured at worst case, with margin","hint":"Stack painting or static analysis per task and for interrupts. Keep at least 25% margin.","tags":[],"severity":"critical"},{"id":"mem-map-4","text":"Stack overflow is detected (MPU guard, canary, or RTOS check)","hint":"An overflow that silently corrupts RAM is the hardest bug to find in the field.","tags":[],"severity":"major"},{"id":"mem-map-5","text":"Dynamic allocation is avoided after startup, or fragmentation is bounded","hint":"Prefer static or pool allocation. If malloc is used, measure the high-water mark under long runs.","tags":[],"severity":"major"},{"id":"mem-map-6","text":"Variables shared with DMA or the bootloader are placed in named sections","hint":"So their addresses don't move when unrelated code changes.","tags":[],"severity":"minor"}]},{"id":"mem-nv","title":"Non-Volatile Storage","tags":[],"items":[{"id":"mem-nv-1","text":"Stored data has a version, a length, and a CRC","hint":"So the firmware can tell blank, corrupt, and old-format data apart.","tags":[],"severity":"major"},{"id":"mem-nv-2","text":"Writes survive power loss at any point without corrupting stored data","hint":"Double-buffered records or a journaling file system. Test by cutting power during writes.","tags":[],"severity":"critical"},{"id":"mem-nv-3","text":"Flash or EEPROM wear is estimated over the product's life and within endurance","hint":"Writes per day × years ÷ wear-leveling factor against the rated cycles.","tags":[],"severity":"major"},{"id":"mem-nv-4","text":"Defaults are restored cleanly on a first boot or a factory reset","hint":"Including what a factory reset must keep (calibration, serial number, keys).","tags":[],"severity":"minor"},{"id":"mem-nv-5","text":"The file system or log handles a full or failed storage device","hint":"Logs roll over. Writes report errors instead of hanging.","tags":["storage"],"severity":"major"}]},{"id":"mem-fault","title":"Faults & Watchdog","tags":[],"items":[{"id":"mem-fault-1","text":"A watchdog is enabled in release builds and can't be starved by a single stuck task","hint":"Feed it only when every monitored task has checked in, not from a timer interrupt.","tags":[],"severity":"critical"},{"id":"mem-fault-2","text":"Fault handlers (HardFault, bus, or memory faults) capture state for later diagnosis","hint":"Save the PC, LR, and fault registers to retained RAM or flash, then reset.","tags":[],"severity":"major"},{"id":"mem-fault-3","text":"Asserts are defined for release builds (log and reset), not compiled out silently","hint":"Decide deliberately what an assert does in the field.","tags":[],"severity":"major"},{"id":"mem-fault-4","text":"The firmware detects and limits reset loops","hint":"After N quick resets, fall back to a safe mode or the last good image.","tags":[],"severity":"major"},{"id":"mem-fault-5","text":"Brownout detection is set at a level where the flash and the MCU still work","hint":"Pick the BOR level from the datasheet's flash-write minimum voltage.","tags":[],"severity":"minor"},{"id":"mem-fault-6","text":"The MPU protects code, stacks, and peripherals where the core has one","hint":"At least a guard region below each stack and no-execute on RAM.","tags":[],"severity":"minor"}]}]},{"id":"concurrency","title":"RTOS, Interrupts & Concurrency","short":"Concurrency","version":1,"description":"Review of interrupt handling, tasks and scheduling, shared data, timing analysis, and the RTOS configuration.","sections":[{"id":"rtos-isr","title":"Interrupts","tags":[],"items":[{"id":"rtos-isr-1","text":"Interrupt priorities are assigned deliberately and documented","hint":"Including which priorities may call RTOS functions (e.g. configMAX_SYSCALL_INTERRUPT_PRIORITY).","tags":[],"severity":"major"},{"id":"rtos-isr-2","text":"Interrupt handlers are short, and defer work to tasks or the main loop","hint":"Measure the worst-case ISR time. Long ISRs delay everything below them.","tags":[],"severity":"major"},{"id":"rtos-isr-3","text":"Interrupts are cleared correctly, with no lost or repeated events","hint":"Clear before return and allow for the write-buffer delay on Cortex-M parts.","tags":[],"severity":"major"},{"id":"rtos-isr-4","text":"Critical sections that disable interrupts are short and measured","hint":"Worst-case interrupt latency is the longest critical section plus the higher-priority ISRs.","tags":[],"severity":"minor"},{"id":"rtos-isr-5","text":"Unused interrupt vectors go to a handler that logs and resets","hint":"Not an empty infinite loop that looks like a hang.","tags":[],"severity":"minor"}]},{"id":"rtos-task","title":"Tasks & Scheduling","tags":["rtos","bare-metal"],"items":[{"id":"rtos-task-1","text":"Each task's purpose, priority, period, and stack size are listed in one place","hint":"A table in the architecture doc, kept in sync with the code.","tags":["rtos"],"severity":"major"},{"id":"rtos-task-2","text":"Worst-case response times meet the timing requirements","hint":"Measure with a trace tool (e.g. SystemView, Tracealyzer) under full load.","tags":["rtos"],"severity":"major"},{"id":"rtos-task-3","text":"Blocking calls have timeouts, and the timeout case is handled","hint":"portMAX_DELAY should be rare and justified.","tags":["rtos"],"severity":"major"},{"id":"rtos-task-4","text":"CPU load is measured, with margin at peak","hint":"Idle-task time under the worst realistic load. Keep headroom for future features.","tags":["rtos"],"severity":"minor"},{"id":"rtos-task-5","text":"RTOS configuration options are reviewed (tick rate, assert, stack checking, run-time stats)","hint":"Turn on configASSERT and stack checking in all builds that are tested.","tags":["rtos"],"severity":"minor"},{"id":"rtos-task-6","text":"The main loop's worst-case cycle time meets every deadline it serves","hint":"In a superloop, one slow function delays everything. Measure the longest pass.","tags":["bare-metal"],"severity":"major"}]},{"id":"rtos-sync","title":"Shared Data","tags":[],"items":[{"id":"rtos-sync-1","text":"Data shared between tasks or with ISRs is protected or provably atomic","hint":"Mutex, critical section, queue, or a single-writer design. volatile alone doesn't make access atomic.","tags":[],"severity":"critical"},{"id":"rtos-sync-2","text":"Lock ordering is defined, so there are no deadlocks","hint":"Document the order. Never take a mutex inside an ISR.","tags":[],"severity":"major"},{"id":"rtos-sync-3","text":"Priority inversion is prevented where a low-priority task holds a shared resource","hint":"Use mutexes with priority inheritance, not binary semaphores.","tags":["rtos"],"severity":"major"},{"id":"rtos-sync-4","text":"Queue and buffer depths are sized for bursts, and overflow is detected and counted","hint":"A full queue drops data silently unless the code checks the return value.","tags":[],"severity":"major"},{"id":"rtos-sync-5","text":"Non-reentrant library calls are not used from several contexts","hint":"E.g. strtok, some printf implementations, and newlib's malloc without locks.","tags":[],"severity":"minor"}]}]},{"id":"power","title":"Power Management","short":"Power","version":1,"description":"Review of low-power modes, the energy budget, battery handling, and behavior on brownout and power loss.","sections":[{"id":"pwr-mode","title":"Low-Power Modes","tags":["battery","low-power"],"items":[{"id":"pwr-mode-1","text":"An energy budget exists per mode, and measured current matches it","hint":"Measure with a power analyzer across a full duty cycle, not just in sleep.","tags":["battery","low-power"],"severity":"major"},{"id":"pwr-mode-2","text":"The system enters its lowest usable sleep mode whenever it's idle","hint":"E.g. FreeRTOS tickless idle. Check that nothing holds the clocks on.","tags":["battery","low-power"],"severity":"major"},{"id":"pwr-mode-3","text":"Every wake-up source is known, and unexpected wake-ups are counted","hint":"Spurious wake-ups are a common reason for short battery life.","tags":["battery","low-power"],"severity":"major"},{"id":"pwr-mode-4","text":"Peripherals and external parts are powered down or put to sleep when unused","hint":"Including sensors, radios, and pull-ups on idle buses.","tags":["battery","low-power"],"severity":"minor"},{"id":"pwr-mode-5","text":"Debug builds that block sleep are not what's measured or shipped","hint":"Debug interfaces often keep clocks running.","tags":["battery","low-power"],"severity":"minor"}]},{"id":"pwr-bat","title":"Battery","tags":["battery"],"items":[{"id":"pwr-bat-1","text":"State of charge is estimated with a method suited to the chemistry","hint":"Voltage alone is poor for Li-ion under load. Use a fuel gauge or coulomb counting.","tags":["battery"],"severity":"major"},{"id":"pwr-bat-2","text":"Charging respects the cell's temperature and voltage limits","hint":"Don't charge Li-ion below 0 °C. Firmware-controlled chargers need independent hardware protection.","tags":["battery"],"severity":"critical"},{"id":"pwr-bat-3","text":"Low-battery behavior is graceful: warn, save state, then shut down","hint":"Shut down before brownout corrupts storage.","tags":["battery"],"severity":"major"},{"id":"pwr-bat-4","text":"Shipping or storage mode keeps self-discharge within shelf-life targets","tags":["battery"],"severity":"minor"}]},{"id":"pwr-loss","title":"Brownout & Power Loss","tags":[],"items":[{"id":"pwr-loss-1","text":"Power loss is detected early enough to finish critical writes","hint":"Use the PVD or a supply monitor, and know the hold-up time from bulk capacitance.","tags":[],"severity":"major"},{"id":"pwr-loss-2","text":"The device recovers to a correct state after a power cut at any moment","hint":"Automate cycles at random points (e.g. 1,000 cuts) and check state and storage each time.","tags":[],"severity":"major"},{"id":"pwr-loss-3","text":"Behavior on slow-rising and dipping supplies is tested","hint":"Slow ramps and short dips can leave the MCU half-reset without a supervisor.","tags":[],"severity":"minor"}]}]},{"id":"comms","title":"Communications","short":"Comms","version":1,"description":"Review of wired interfaces, wireless links, cloud connectivity, and USB: protocols, timeouts, robustness, and certification settings.","sections":[{"id":"com-wire","title":"Wired Interfaces","tags":[],"items":[{"id":"com-wire-1","text":"Every protocol and message format is documented and versioned","hint":"Including byte order, framing, checksums, and the meaning of every field.","tags":[],"severity":"major"},{"id":"com-wire-2","text":"Receivers handle malformed, truncated, and out-of-order messages","hint":"Validate length and checksum before parsing. Fuzz the parser.","tags":[],"severity":"major"},{"id":"com-wire-3","text":"Timeouts and retries are defined for every request and response","hint":"With a backoff, and a defined outcome when retries run out.","tags":[],"severity":"major"},{"id":"com-wire-4","text":"Debug and service ports are disabled or protected in production builds","hint":"A console that accepts commands is an attack surface.","tags":[],"severity":"minor"},{"id":"com-wire-5","text":"Link errors are counted and visible in diagnostics","hint":"CRC errors, framing errors, and timeouts per interface.","tags":[],"severity":"minor"}]},{"id":"com-rf","title":"Wireless","tags":["wireless"],"items":[{"id":"com-rf-1","text":"Regional radio settings (channels, power, duty cycle) match the certifications","hint":"Firmware must not be able to exceed the certified configuration.","tags":["wireless"],"severity":"critical"},{"id":"com-rf-2","text":"Test modes for radio certification are available, and locked out of production use","hint":"Labs need continuous TX and fixed-channel modes. Document how to enter them.","tags":["wireless"],"severity":"major"},{"id":"com-rf-3","text":"Connection loss and reconnection are handled with backoff","hint":"Thousands of devices reconnecting at once can overload the network or the backend.","tags":["wireless"],"severity":"major"},{"id":"com-rf-4","text":"The device works, or degrades gracefully, without connectivity","hint":"Local control keeps working when Wi-Fi or the cloud is down.","tags":["wireless"],"severity":"major"},{"id":"com-rf-5","text":"Provisioning (joining a network) is tested with real phones and access points","hint":"Include mixed-band networks, hidden SSIDs, captive portals, and wrong passwords.","tags":["wireless"],"severity":"minor"},{"id":"com-rf-6","text":"Coexistence between radios on the same device is managed","hint":"E.g. Wi-Fi and BLE sharing a 2.4 GHz front end.","tags":["wireless"],"severity":"minor"}]},{"id":"com-cloud","title":"Cloud & Protocols","tags":["cloud"],"items":[{"id":"com-cloud-1","text":"TLS is used with certificate validation, and a way to rotate root certificates","hint":"Pin to a set of roots that can be updated by OTA, not a single leaf certificate.","tags":["cloud"],"severity":"critical"},{"id":"com-cloud-2","text":"The device-to-cloud API is versioned, so old firmware keeps working after backend changes","hint":"Old firmware will be in the field for years.","tags":["cloud"],"severity":"major"},{"id":"com-cloud-3","text":"Messages are queued or dropped by a defined policy while offline","hint":"Bounded queue, with oldest-first or priority dropping.","tags":["cloud"],"severity":"major"},{"id":"com-cloud-4","text":"Time is synchronized securely before it's used for certificates or schedules","hint":"A device with no RTC battery boots in 1970, and certificate checks fail.","tags":["cloud"],"severity":"minor"},{"id":"com-cloud-5","text":"Telemetry volume and data costs are estimated per device per month","hint":"Matters for cellular and for backend sizing.","tags":["cloud"],"severity":"minor"}]},{"id":"com-usb","title":"USB","tags":["usb"],"items":[{"id":"com-usb-1","text":"USB descriptors use the client's own VID/PID, not the vendor's example IDs","hint":"Example IDs collide with other products and aren't licensed for shipping.","tags":["usb"],"severity":"major"},{"id":"com-usb-2","text":"Enumeration works on Windows, macOS, and Linux hosts, and through hubs","tags":["usb"],"severity":"major"},{"id":"com-usb-3","text":"Suspend, resume, and cable unplug during transfers are handled","tags":["usb"],"severity":"minor"}]}]},{"id":"security","title":"Security","short":"Security","version":1,"description":"Review of secure boot, debug access, keys and credentials, input handling, vulnerability management, and privacy.","sections":[{"id":"sec-boot","title":"Secure Boot & Debug","tags":[],"items":[{"id":"sec-boot-1","text":"Debug ports (SWD/JTAG) are locked or disabled on production units","hint":"Set read-out protection or debug authentication as a production step, and verify it at end of line.","tags":[],"severity":"critical"},{"id":"sec-boot-2","text":"Only signed firmware can boot, or the decision not to is documented","hint":"Secure boot with a root of trust in ROM or locked flash.","tags":["security-sensitive","ota"],"severity":"major"},{"id":"sec-boot-3","text":"Anti-rollback prevents installing an older, vulnerable image","hint":"A monotonic security version in OTP or protected storage.","tags":["security-sensitive"],"severity":"major"},{"id":"sec-boot-4","text":"Bootloader and option-byte protection can't be undone without erasing secrets","hint":"Check what an attacker can do with the regression from RDP level 1 to level 0.","tags":["security-sensitive"],"severity":"minor"}]},{"id":"sec-key","title":"Keys & Credentials","tags":[],"items":[{"id":"sec-key-1","text":"No secrets (keys, passwords, API tokens) are in the source code or the image","hint":"Search the repository history too. Shared secrets across all devices are a single point of failure.","tags":[],"severity":"critical"},{"id":"sec-key-2","text":"Each device has unique credentials, provisioned in production","hint":"Per-device certificates or keys, injected in a controlled step and recorded.","tags":["cloud","security-sensitive"],"severity":"critical"},{"id":"sec-key-3","text":"Keys are stored in protected storage (secure element, TrustZone, encrypted flash)","hint":"Not in plain external flash that can be read with a clip.","tags":["security-sensitive","cloud"],"severity":"major"},{"id":"sec-key-4","text":"User credentials (Wi-Fi passwords, accounts) are encrypted at rest and never logged","hint":"Check debug logs, crash dumps, and support bundles.","tags":["wireless","cloud"],"severity":"major"},{"id":"sec-key-5","text":"There is a plan for revoking and rotating keys","hint":"What happens when one device's key leaks? When the signing key leaks?","tags":["security-sensitive","cloud"],"severity":"minor"}]},{"id":"sec-in","title":"Input Handling","tags":[],"items":[{"id":"sec-in-1","text":"All external input is validated for length and range before use","hint":"Network, BLE, USB, serial, files, and sensor data. No unchecked memcpy from a packet.","tags":[],"severity":"critical"},{"id":"sec-in-2","text":"Banned functions (strcpy, sprintf, gets) are not used, or are flagged by the build","hint":"Use bounded versions and enforce it with a linter rule.","tags":[],"severity":"major"},{"id":"sec-in-3","text":"Parsers for external data are fuzzed","hint":"Even a short fuzzing run off target finds most buffer bugs in a parser.","tags":["security-sensitive","cloud","wireless"],"severity":"major"},{"id":"sec-in-4","text":"Stack protection, and other compiler and linker hardening, are enabled","hint":"-fstack-protector-strong, and the MPU marking RAM non-executable.","tags":[],"severity":"minor"}]},{"id":"sec-vul","title":"Vulnerabilities & Compliance","tags":[],"items":[{"id":"sec-vul-1","text":"Third-party components are checked against known vulnerabilities (CVEs)","hint":"Use the SBOM. Repeat at each release and on a schedule after launch.","tags":[],"severity":"major"},{"id":"sec-vul-2","text":"The applicable cybersecurity rules for the target markets are identified","hint":"E.g. EN 18031 for radio products in the EU (RED), the Cyber Resilience Act, ETSI EN 303 645, the US Cyber Trust Mark.","tags":["wireless","cloud"],"severity":"major"},{"id":"sec-vul-3","text":"There is a vulnerability disclosure contact and a patch process","hint":"Required by several of the rules above. Agree who owns it with the client.","tags":["wireless","cloud"],"severity":"minor"},{"id":"sec-vul-4","text":"A threat model lists assets, attackers, and mitigations","hint":"Even a one-page STRIDE table focuses the security review.","tags":["security-sensitive"],"severity":"minor"},{"id":"sec-vul-5","text":"Personal data collected by the device is listed, minimized, and disclosed","hint":"Location, schedules, usage patterns. Check the privacy policy matches what the firmware sends.","tags":["cloud"],"severity":"minor"}]}]},{"id":"update","title":"Bootloader & Updates","short":"Updates","version":1,"description":"Review of the bootloader, the update process over the air or in the field, failure recovery, and data migration between versions.","sections":[{"id":"ota-bl","title":"Bootloader","tags":[],"items":[{"id":"ota-bl-1","text":"The bootloader is as small and simple as possible, and is never updated in the field (or safely if it is)","hint":"A bootloader bug in the field can brick every device. Treat any bootloader update as a last resort.","tags":[],"severity":"major"},{"id":"ota-bl-2","text":"The bootloader validates the application image (CRC or signature) before jumping to it","hint":"And knows what to do when no valid image exists.","tags":[],"severity":"major"},{"id":"ota-bl-3","text":"The handoff to the application resets peripherals, interrupts, and the stack pointer","hint":"Leftover bootloader state is a classic source of rare startup bugs.","tags":[],"severity":"minor"},{"id":"ota-bl-4","text":"A recovery path exists for a device with no valid image (USB, UART, test pads)","hint":"Document it for the service team.","tags":[],"severity":"minor"}]},{"id":"ota-upd","title":"Update Process","tags":["ota"],"items":[{"id":"ota-upd-1","text":"A failed or interrupted update leaves the device running the previous image","hint":"A/B slots or a protected recovery image. Test power loss at every stage of the update.","tags":["ota"],"severity":"critical"},{"id":"ota-upd-2","text":"A new image must confirm it works before it's made permanent, or it rolls back","hint":"Self-test after boot, then confirm. A watchdog reset before confirmation reverts.","tags":["ota"],"severity":"critical"},{"id":"ota-upd-3","text":"Images are authenticated (signed) and integrity-checked before install","hint":"Check the signature before writing to the boot slot, not after.","tags":["ota"],"severity":"major"},{"id":"ota-upd-4","text":"Updates are compatible with the hardware revision and the current version","hint":"The image header names the hardware it's for. Refuse a mismatch.","tags":["ota"],"severity":"major"},{"id":"ota-upd-5","text":"Staged rollout and a way to stop a bad release are planned","hint":"E.g. 1%, 10%, then everyone, with a halt if crash or rollback rates go up.","tags":["ota","cloud"],"severity":"major"},{"id":"ota-upd-6","text":"Download resumes after a dropped connection","hint":"Large images over weak Wi-Fi rarely finish in one go.","tags":["ota"],"severity":"minor"},{"id":"ota-upd-7","text":"Updates don't interrupt critical operation","hint":"Schedule or defer the reboot. E.g. not mid-cycle on an HVAC call.","tags":["ota"],"severity":"minor"}]},{"id":"ota-mig","title":"Data Migration","tags":[],"items":[{"id":"ota-mig-1","text":"Stored settings migrate forward across every version that can update to this one","hint":"Test from each released version, not only the last one.","tags":[],"severity":"major"},{"id":"ota-mig-2","text":"A rollback to the previous image can still read the data the new image wrote","hint":"Or the migration happens only after the new image is confirmed.","tags":["ota"],"severity":"minor"}]}]},{"id":"quality","title":"Code Quality","short":"Code quality","version":1,"description":"Review of the coding standard, compiler warnings, static analysis, code review practice, and maintainability.","sections":[{"id":"cq-std","title":"Standards & Static Analysis","tags":[],"items":[{"id":"cq-std-1","text":"A coding standard is chosen and enforced (e.g. MISRA C, CERT C, Barr Group)","hint":"Record deviations with a reason, rather than switching rules off globally.","tags":[],"severity":"major"},{"id":"cq-std-2","text":"The build is warning-free with a strict warning set, and warnings fail CI","hint":"E.g. -Wall -Wextra -Werror with -Wconversion where practical.","tags":[],"severity":"major"},{"id":"cq-std-3","text":"Static analysis runs in CI, and findings are triaged","hint":"cppcheck, clang-tidy, or a commercial tool. Keep a reviewed baseline so new findings stand out.","tags":[],"severity":"major"},{"id":"cq-std-4","text":"Formatting is automated (e.g. clang-format)","hint":"So code review is about behavior, not whitespace.","tags":[],"severity":"minor"},{"id":"cq-std-5","text":"MISRA compliance is reported with a deviation record where the client or standard asks for it","hint":"Usually required for safety and automotive work.","tags":["safety","medical"],"severity":"major"}]},{"id":"cq-rev","title":"Code Review & Structure","tags":[],"items":[{"id":"cq-rev-1","text":"Every change to the main branch is reviewed by a second engineer","hint":"Use pull requests with required review.","tags":[],"severity":"major"},{"id":"cq-rev-2","text":"Functions are small and their complexity is measured","hint":"Flag cyclomatic complexity above about 15 for review.","tags":[],"severity":"minor"},{"id":"cq-rev-3","text":"Magic numbers are named, and units are clear in names or types","hint":"timeout_ms, temp_c_x10. Unit mix-ups cause real bugs.","tags":[],"severity":"minor"},{"id":"cq-rev-4","text":"Comments explain why, and public interfaces are documented","hint":"Header comments on each module's API, generated docs if useful.","tags":[],"severity":"minor"},{"id":"cq-rev-5","text":"Dead code and commented-out code are removed","hint":"Version control keeps the history.","tags":[],"severity":"minor"},{"id":"cq-rev-6","text":"Integer overflow, sign conversion, and undefined behavior are reviewed in arithmetic","hint":"Especially in time calculations, scaling, and buffer index math.","tags":[],"severity":"major"}]}]},{"id":"test","title":"Testing & Verification","short":"Testing","version":1,"description":"Review of unit and integration tests, hardware-in-the-loop and system testing, robustness and long-run testing, and test reporting.","sections":[{"id":"tst-unit","title":"Unit & Integration Tests","tags":[],"items":[{"id":"tst-unit-1","text":"Unit tests run off target in CI on every change","hint":"E.g. Unity, CppUTest, or GoogleTest on the host, with the hardware layer mocked.","tags":[],"severity":"major"},{"id":"tst-unit-2","text":"Code coverage is measured, and untested critical modules are known","hint":"Coverage is a guide, not a target. Look at what isn't covered.","tags":[],"severity":"minor"},{"id":"tst-unit-3","text":"Logic that decides safety or outputs has thorough tests, including boundaries","hint":"State machines, control logic, schedulers, parsers.","tags":[],"severity":"major"},{"id":"tst-unit-4","text":"Structural coverage meets what the safety standard requires","hint":"Statement, branch, or MC/DC coverage depending on class or SIL.","tags":["safety","medical"],"severity":"major"}]},{"id":"tst-sys","title":"Hardware-in-the-Loop & System Tests","tags":[],"items":[{"id":"tst-sys-1","text":"Automated tests run on real hardware for each release candidate","hint":"A HIL rig, or at least scripted bench tests with a pass or fail result.","tags":[],"severity":"major"},{"id":"tst-sys-2","text":"Every requirement has a test, and results are recorded against the build that was tested","hint":"Use the Requirements tab: link each requirement to its check and record the evidence.","tags":[],"severity":"major"},{"id":"tst-sys-3","text":"Tests run on the current hardware revision, and differences from earlier boards are known","hint":"A test pass on EVT boards may not hold on DVT boards.","tags":[],"severity":"major"},{"id":"tst-sys-4","text":"Manual test procedures are written so anyone can repeat them","tags":[],"severity":"minor"},{"id":"tst-sys-5","text":"Interoperability is tested with real phones, apps, routers, and backends","hint":"Keep a matrix of tested versions.","tags":["wireless","cloud"],"severity":"major"}]},{"id":"tst-rob","title":"Robustness & Long-Run Tests","tags":[],"items":[{"id":"tst-rob-1","text":"Soak tests run for days under realistic load without resets or memory growth","hint":"Track heap, stack, queues, and the reset count over the run.","tags":[],"severity":"major"},{"id":"tst-rob-2","text":"Fault injection covers sensor failure, comms loss, storage failure, and power loss","hint":"Each specified fault behavior should have a test that forces it.","tags":[],"severity":"major"},{"id":"tst-rob-3","text":"The firmware is tested during EMC and ESD testing, with its behavior recorded","hint":"Note any reset, lockup, or corrupt display, and which recover on their own.","tags":[],"severity":"major"},{"id":"tst-rob-4","text":"Behavior is tested at temperature extremes","hint":"Oscillator startup, flash writes, and sensor accuracy change with temperature.","tags":[],"severity":"minor"},{"id":"tst-rob-5","text":"Clock and timer wrap-around are tested by starting timers near rollover","hint":"Rather than waiting 49 days.","tags":[],"severity":"minor"}]}]},{"id":"release","title":"Build, Release & Production","short":"Release","version":1,"description":"Review of the build system, versioning, release records, factory programming and provisioning, and the release package.","sections":[{"id":"rel-build","title":"Build & Versioning","tags":[],"items":[{"id":"rel-build-1","text":"The build is reproducible from a tagged commit with a pinned toolchain","hint":"A container or a documented toolchain version. Build twice and compare hashes.","tags":[],"severity":"major"},{"id":"rel-build-2","text":"Release builds come from CI, not a developer's machine","tags":[],"severity":"major"},{"id":"rel-build-3","text":"The version, git hash, and build date are embedded in the image and readable from the device","hint":"Over the service port, the UI, or the cloud.","tags":[],"severity":"major"},{"id":"rel-build-4","text":"Version numbers follow a written scheme (e.g. semantic versioning)","hint":"And the security version used for anti-rollback is separate from the display version.","tags":[],"severity":"minor"},{"id":"rel-build-5","text":"Release and debug build settings are reviewed (optimization, asserts, logging, debug features)","hint":"Test the configuration you ship.","tags":[],"severity":"major"},{"id":"rel-build-6","text":"The ELF, map file, and symbols are archived for every release","hint":"Needed to decode crash dumps from the field.","tags":[],"severity":"minor"}]},{"id":"rel-mfg","title":"Manufacturing & Provisioning","tags":[],"items":[{"id":"rel-mfg-1","text":"The factory programming procedure, image, and fixture are documented and version-controlled","hint":"Including the image hash the line should verify.","tags":[],"severity":"major"},{"id":"rel-mfg-2","text":"Production test firmware or test modes check every interface on the board","hint":"Coordinate with the EE bring-up and the factory test plan.","tags":[],"severity":"major"},{"id":"rel-mfg-3","text":"Serial numbers, MAC addresses, and calibration are written and recorded per unit","hint":"Traceable to the board, the image, and the test result.","tags":[],"severity":"major"},{"id":"rel-mfg-4","text":"Device locking (debug, read-out protection) is applied and verified at end of line","hint":"An unlocked unit shipping is a security and IP leak.","tags":[],"severity":"critical"},{"id":"rel-mfg-5","text":"Per-device keys and certificates are provisioned in a secure, logged step","hint":"Keys never exist in plain files on factory PCs longer than needed.","tags":["cloud","security-sensitive"],"severity":"major"},{"id":"rel-mfg-6","text":"Programming time per unit meets the line's cycle-time target","tags":["high-volume"],"severity":"minor"}]},{"id":"rel-pkg","title":"Release Package","tags":[],"items":[{"id":"rel-pkg-1","text":"Release notes list changes, known issues, and the tested hardware revisions","tags":[],"severity":"major"},{"id":"rel-pkg-2","text":"The SBOM and license notices are produced for the release","hint":"Open-source licenses may require notices in the product documentation or UI.","tags":[],"severity":"major"},{"id":"rel-pkg-3","text":"Source and build instructions are handed over as the contract requires","hint":"Agree what the client receives: source, binaries, keys, toolchain.","tags":[],"severity":"minor"},{"id":"rel-pkg-4","text":"Signing keys are held by the agreed owner, with a backup and access control","hint":"Losing the signing key means no more updates. Agree with the client who holds it.","tags":["ota"],"severity":"major"}]}]}];
